bool resolve_bool_expr(struct xkb_context *ctx, const ExprDef *expr, bool *set_rtrn) {
    if (!ctx || !expr || !set_rtrn) {
        return false;
    }

    switch (expr->type) {
        case EXPR_BOOL_CONST: {
            if (expr->value.bool_val == true || expr->value.bool_val == false) {
                *set_rtrn = expr->value.bool_val;
                return true;
            }
            break;
        }
        case EXPR_IDENT: {
            if (strcmp(expr->value.ident, "true") == 0) {
                *set_rtrn = true;
                return true;
            } else if (strcmp(expr->value.ident, "false") == 0) {
                *set_rtrn = false;
                return true;
            } else {
                xkb_context_log(ctx, XKB_LOG_LEVEL_ERROR, "Unknown identifier: %s\n", expr->value.ident);
                return false;
            }
        }
        case EXPR_FIELD_REF: {
            xkb_context_log(ctx, XKB_LOG_LEVEL_ERROR, "Field references are not supported in boolean expressions.\n");
            return false;
        }
        case EXPR_UNARY_OP: {
            xkb_context_log(ctx, XKB_LOG_LEVEL_ERROR, "Unary operations are not supported in boolean expressions.\n");
            return false;
        }
        default: {
            xkb_context_log(ctx, XKB_LOG_LEVEL_ERROR, "Unsupported expression type.\n");
            return false;
        }
    }

    return false;
}
